package bowling

import "errors"

var (
	errNegativeRoll   = errors.New("negative roll is invalid")
	errTooManyPins    = errors.New("pin count exceeds pins on the lane")
	errGameComplete   = errors.New("cannot roll after game is over")
	errIncompleteGame = errors.New("score cannot be taken until the end of the game")
)

// Game keeps track of the rolls in a game of bowling.
type Game struct {
	rolls      []int // every roll, in order
	frame      int   // 0-based index of the frame currently being played
	framePins  int   // pins knocked down in the current frame
	tenthFirst int   // first roll of the tenth frame
	tenthRolls int   // number of rolls taken in the tenth frame
}

// NewGame returns a game with no rolls recorded yet.
func NewGame() *Game {
	return &Game{}
}

// gameComplete reports whether all ten frames have been played.
func (g *Game) gameComplete() bool {
	if g.frame < 9 {
		return false
	}
	switch g.tenthRolls {
	case 0, 1:
		return false
	case 2:
		// The tenth frame ends after two rolls only when it is open;
		// a spare still needs one bonus roll.
		return g.framePins < 10
	default:
		return g.framePins >= 10
	}
}

// Roll records a throw of `pins` pins.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errNegativeRoll
	}
	if g.gameComplete() {
		return errGameComplete
	}
	if pins > 10 {
		return errTooManyPins
	}

	if g.frame < 9 {
		if pins > 10-g.framePins {
			return errTooManyPins
		}
	} else {
