package bowling

import "errors"

var (
	errNegativeRoll   = errors.New("negative roll is invalid")
	errTooManyPins    = errors.New("pin count exceeds pins on the lane")
	errGameComplete   = errors.New("cannot roll after game is over")
	errIncompleteGame = errors.New("score cannot be taken until the end of the game")
)

// Game keeps track of the rolls in a game of bowling.
type Game struct {
	rolls      []int // every roll, in order
	frame      int   // 0-based index of the frame currently being played
	framePins  int   // pins knocked down in the current frame
	tenthFirst int   // first roll of the tenth frame
	tenthRolls int   // number of rolls taken in the tenth frame
}

// NewGame returns a game with no rolls recorded yet.
func NewGame() *Game {
	return &Game{}
}

// gameComplete reports whether all ten frames have been played.
func (g *Game) gameComplete() bool {
	if g.frame < 9 {
		return false
	}
	switch g.tenthRolls {
	case 0, 1:
		return false
	case 2:
		// The tenth frame ends after two rolls only when it is open;
		// a spare still needs one bonus roll.
		return g.framePins < 10
	default:
		return g.framePins >= 10
	}
}

// Roll records a throw that knocked down pins.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errNegativeRoll
	}
	if g.gameComplete() {
		return errGameComplete
	}
	if pins > 10 {
		return errTooManyPins
	}

	if g.frame < 9 {
		if pins > 10-g.framePins {
			return errTooManyPins
		}
	} else {
		switch g.tenthRolls {
		case 1:
			// A strike leaves the lane full for the next throw.
			if g.tenthFirst < 10 && pins > 10-g.framePins {
				return errTooManyPins
			}
		case 2:
			// If the tenth frame opened with a strike, the two bonus
			// throws form a normal frame.
			if g.tenthFirst == 10 {
				if last := g.rolls[len(g.rolls)-1]; last < 10 && pins > 10-last {
					return errTooManyPins
				}
			}
		}
	}

	g.rolls = append(g.rolls, pins)
	g.framePins += pins

	if g.frame < 9 {
		if g.framePins == 10 {
			g.frame++
			g.framePins = 0
		}
	} else {
		if g.tenthRolls == 0 {
			g.tenthFirst = pins
		}
		g.tenthRolls++
	}

	return nil
}

// Score returns the total score once the game is complete.
func (g *Game) Score() (int, error) {
	if !g.gameComplete() {
		return 0, errIncompleteGame
	}

	rolls := g.rolls
	total := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		if frame < 9 {
			switch {
			case rolls[i] == 10:
				// Strike: 10 plus the next two rolls.
				total += 10 + rolls[i+1] + rolls[i+2]
				i++
			case rolls[i]+rolls[i+1] == 10:
				// Spare: 10 plus the next roll.
				total += 10 + rolls[i+2]
				i += 2
			default:
				total += rolls[i] + rolls[i+1]
				i += 2
			}
		} else {
			// Tenth frame: the sum of its rolls, bonus included.
			for ; i < len(rolls); i++ {
				total += rolls[i]
			}
		}
	}
	return total, nil
}

